// AgencyOS/tests/e2e-06-dead-configs.mjs
// ---------------------------------------------------------------------------
// E2E-06 regression: orphaned config surface removed.
//
// Finding: garcia shipped config/order.json while no section consumed it:
//   - src/core/site.js imports 19 config files — order.json is NOT among them,
//   - the only consumer (src/sections/OrderOnline.jsx) destructures
//     SITE.order, which therefore always resolves to undefined,
//   - scripts/schemas.mjs REQUIRED_FILES (the QA contract) lists 19 files —
//     order.json is NOT validated, generated by the template, or present in
//     any other business config directory.
//
// Fix: order.json deleted from businesses/garcia/config and the active
// config root. features/reviews/stats were AUDITED and classified ACTIVE
// (REQUIRED_FILES members, imported into the bundle, consumed by
// About/Testimonials/Stats sections; cafe-luna enables stats + testimonials),
// so they are intentionally untouched.
//
// The suite guards the deletion from every side:
//   - source level: no loader / schema / script may reference order.json,
//   - file level: every business + the active config use the 19-file set,
//   - runtime level: QA passes and the real SSR smoke renders against a
//     config tree without order.json.
// ---------------------------------------------------------------------------

import { spawnSync } from 'node:child_process'
import { readFileSync, readdirSync } from 'node:fs'
import path from 'node:path'
import { fileURLToPath } from 'node:url'

import { REQUIRED_FILES } from '../../scripts/schemas.mjs'

const REPO = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '..', '..')
const CONFIG_DIR = path.join(REPO, 'config')
const BUSINESSES = path.join(REPO, 'businesses')
const SCRIPTS_DIR = path.join(REPO, 'scripts')

let passed = 0
let failed = 0
const fail = (msg) => {
  failed++
  console.log('FAIL ' + msg)
}
const pass = (msg) => {
  passed++
  console.log('PASS ' + msg)
}
const check = (cond, msg) => (cond ? pass(msg) : fail(msg))

const run = (file, args = []) => spawnSync(process.execPath, [file, ...args], { cwd: REPO, encoding: 'utf8' })
const listConfig = (dir) => readdirSync(dir).filter((f) => f.endsWith('.json')).sort()

// ---- 0. Schema contract: QC schema must not validate the removed file ----
console.log('== e2e-06 schema/source guards ==')
check(!REQUIRED_FILES.includes('order.json'), 'schemas.mjs REQUIRED_FILES does not include order.json')

const siteJs = readFileSync(path.join(REPO, 'src', 'core', 'site.js'), 'utf8')
check(!siteJs.includes('order.json'), 'src/core/site.js contains no order.json import')
check(!siteJs.includes("'order'") && !siteJs.includes('"order"'), 'src/core/site.js contains no "order" config key import')

const scriptRefs = []
for (const f of readdirSync(SCRIPTS_DIR).filter((f) => f.endsWith('.mjs'))) {
  const text = readFileSync(path.join(SCRIPTS_DIR, f), 'utf8')
  if (text.includes('order.json')) scriptRefs.push(f)
}
check(scriptRefs.length === 0, `no scripts/*.mjs references order.json (got: ${scriptRefs.join(', ') || 'none'})`)

// ---- 1. File-set contract: every business uses the same 19-file set ----
console.log('== e2e-06 config file-set contract ==')
const template = listConfig(path.join(BUSINESSES, '_template', 'config'))
check(template.length === REQUIRED_FILES.length, `template config has ${REQUIRED_FILES.length} files (got ${template.length})`)
check(template.every((f) => REQUIRED_FILES.includes(f)), 'template file set equals REQUIRED_FILES exactly')

for (const name of readdirSync(BUSINESSES).filter((d) => d.startsWith('_'))) {
  const files = listConfig(path.join(BUSINESSES, name, 'config'))
  check(files.length === template.length && files.every((f) => template.includes(f)),
    `_internal business "${name}" uses the same ${template.length}-file set`)
}
for (const name of readdirSync(BUSINESSES).filter((d) => !d.startsWith('_'))) {
  const files = listConfig(path.join(BUSINESSES, name, 'config'))
  check(files.length === template.length && files.every((f) => template.includes(f)),
    `business "${name}" uses the same ${template.length}-file set`)
}

// ---- 2. Active config: never re-introduces the removed file ----
console.log('== e2e-06 active config ==')
const activeFiles = listConfig(CONFIG_DIR)
check(!activeFiles.includes('order.json'), 'active config/ has no order.json')

// ---- 3. Runtime proof: QA passes and SSR renders without order.json ----
console.log('== e2e-06 runtime proof ==')
const qa = run(path.join(REPO, 'scripts', 'qa.mjs'))
check(qa.status === 0, `qa.mjs exits 0 on the config tree without order.json (got ${qa.status})`)

const smoke = run(path.join(REPO, 'scripts', 'ssr-smoke.mjs'))
check(smoke.status === 0, `ssr-smoke.mjs renders the active business without order.json (got ${smoke.status})`)
check(/SSR SMOKE OK/.test(smoke.stdout), 'ssr-smoke output confirms success line')

console.log(`\ne2e-06 dead-configs: ${passed} passed, ${failed} failed`)
process.exit(failed > 0 ? 1 : 0)